<script module>  export const manifiesto = {    id: 'compras',    nombre: 'Compras',    icono: 'bag',    grupo: 'negocio',    orden: 2,    tablas: { compras: '++id, fecha, productoId, anulada', lotes: '++id, productoId, varianteId, fecha, costo, compraId' }  };</script><script>  import { onMount } from 'svelte';  import { listar } from '../../core/db.js';  import { bus } from '../../core/bus.js';  import { avisar, confirmar } from '../../core/state.svelte.js';  import { n, m, fmt, fmtCant, fmtFH, stockVariante } from '../../core/util.js';  import { CompraService } from '../../services/CompraService.js';  import { obtenerPeriodosCerrados } from '../../core/periodos.js';  import Icono from '../../core/Icono.svelte';  let productos = $state([]);  let variantes = $state([]);  let lotes = $state([]);  let compras = $state([]);  let periodosCerrados = $state([]);  let busq = $state('');  let busqDebounced = $state('');  $effect(() => { const t = setTimeout(() => busqDebounced = busq, 200); return () => clearTimeout(t); });  let focusBusq = $state(false);  let paginaHist = $state(1);  const itemsPorPagina = 20;  let procesando = $state(false);  let form = $state({ editId: '', productoId: '', varianteId: '', nombre: '', cantidad: '', costo: '', unidad: '' });  let prodsActivos = $derived(productos.filter(p => !p.archivado));  let resultados = $derived((() => {    const qry = busqDebounced.toLowerCase().trim();    const base = qry ? prodsActivos.filter(p => p.nombre.toLowerCase().includes(qry) || (p.codigo || '').toLowerCase().includes(qry)) : prodsActivos;    return base.slice(0, 12);  })());  let comprasOrdenadas = $derived(compras.filter(c => !c.anulada).sort((a, b) => new Date(b.fecha) - new Date(a.fecha)));  let comprasPaginadas = $derived(comprasOrdenadas.slice((paginaHist - 1) * itemsPorPagina, paginaHist * itemsPorPagina));  let totalPaginas = $derived(Math.max(1, Math.ceil(comprasOrdenadas.length / itemsPorPagina)));  async function recargar() {    [productos, variantes, lotes, compras] = await Promise.all([listar('productos'), listar('productoVariantes'), listar('lotes'), listar('compras')]);    periodosCerrados = await obtenerPeriodosCerrados();  }  function esCerrado(fechaIso) {    const f = new Date(fechaIso);    return periodosCerrados.some(p => new Date(p.inicio) <= f && f <= new Date(p.fin));  }  onMount(() => { recargar(); const off = bus.on('recargar', recargar); return () => off(); });  function seleccionar(p) {    form = { editId: '', productoId: p.id, varianteId: '', nombre: p.nombre, cantidad: '', costo: '', unidad: '' };    busq = '';    focusBusq = false;  }  function seleccionarVariante(v) {    form.varianteId = v.id;    form.unidad = v.unidad || '';  }  function resetForm() {    form = { editId: '', productoId: '', varianteId: '', nombre: '', cantidad: '', costo: '', unidad: '' };  }  function variantesDeProducto(pid) {    return variantes.filter(v => v.productoId === pid && !v.archivado);  }  function loteSinVentas(cid) {    const l = lotes.find(x => x.compraId === cid);    return l ? n(l.cantidadVendida) === 0 : true;  }  function editar(c) {    if (!loteSinVentas(c.id)) return;    form = { editId: c.id, productoId: c.productoId, varianteId: c.varianteId || '', nombre: c.productoNombre, cantidad: String(c.cantidad), costo: String(c.costo), unidad: c.unidad || '' };    window.scrollTo(0, 0);  }  async function eliminar(c) {    if (procesando) return;    if (!loteSinVentas(c.id)) return;    const ok = await confirmar('Eliminar compra', 'Eliminar compra de ' + c.productoNombre + '?');    if (!ok) return;    procesando = true;    try {      const l = lotes.find(x => x.compraId === c.id);      await CompraService.eliminar(c.id, l?.id);      await recargar();      bus.emit('recargar');      avisar('Compra eliminada');    } finally { procesando = false; }  }  async function guardarCompra() {    if (procesando) return;    const cant = n(form.cantidad), costo = n(form.costo);    if (!form.productoId) return avisar('Selecciona producto', 'bad');    if (!form.varianteId) return avisar('Selecciona variante', 'bad');    if (cant <= 0) return avisar('Cantidad debe ser > 0', 'bad');    if (costo < 0) return avisar('Costo invalido', 'bad');    const total = m(cant * costo);    const v = variantes.find(x => x.id === form.varianteId);    procesando = true;    try {      if (form.editId) {        const l = lotes.find(x => x.compraId === form.editId);        if (l && n(l.cantidadVendida) > 0) return avisar('Lote con ventas: no editable', 'bad');        const c = compras.find(x => x.id === form.editId);        await CompraService.editar(c, l, {          compra: { productoId: form.productoId, varianteId: form.varianteId, productoNombre: form.nombre, productoUnidad: form.unidad, cantidad: cant, costo, total, unidad: form.unidad },          lote: { productoId: form.productoId, varianteId: form.varianteId, productoNombre: form.nombre, productoUnidad: form.unidad, cantidadInicial: cant, costo }        });      } else {        await CompraService.registrarExistente({          productoId: form.productoId, varianteId: form.varianteId, nombre: form.nombre, unidad: form.unidad || '',          cantidad: cant, costo, total        });      }      await recargar();      resetForm();      avisar('Compra ' + fmt(total));      bus.emit('recargar');    } catch (e) { avisar(e.message, 'bad'); }    finally { procesando = false; }  }</script><div class='modulo'>  <!-- Registrar Compra --><div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)] mb-3'>    <div class='flex items-center gap-2 font-extrabold text-primary mb-3'>      <Icono nombre='bag' size={18} />      Registrar Compra    </div>    {#if !form.productoId}      <div class='relative mb-2'>        <Icono nombre='search' size={18} class='absolute left-3 top-1/2 -translate-y-1/2 text-muted' />        <input class='w-full pl-10 pr-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' type='text' placeholder='Buscar producto...' bind:value={busq} onfocus={() => focusBusq = true} />      </div>      {#if focusBusq}        <div class='border border-border rounded-[var(--radius-md)] bg-card max-h-64 overflow-y-auto mb-2 shadow-[var(--color-shadow)]'>          <div class='flex justify-between items-center px-3 py-2 text-xs font-extrabold text-muted border-b border-border sticky top-0 bg-card'>            <span>{resultados.length} resultado(s)</span>            <button class='bg-transparent border-none text-danger font-extrabold text-lg cursor-pointer leading-none' onclick={() => { focusBusq = false; busq = ''; }}>×</button>          </div>          {#if resultados.length === 0}            <div class='text-center text-muted py-4 text-sm'>Sin coincidencias</div>          {:else}            {#each resultados as p}              <button class='w-full flex justify-between items-center px-3.5 py-3 text-left border-b border-border last:border-0 text-sm cursor-pointer hover:bg-background active:bg-background transition-colors' onclick={() => seleccionar(p)}>                <span class='font-medium'>{p.nombre}</span>                <span class='text-muted text-xs'>{variantesDeProducto(p.id).length} variantes</span>              </button>            {/each}          {/if}        </div>      {/if}    {:else}      <div class='bg-primary/5 rounded-xl p-3 mb-3 flex justify-between items-center'>        <div>          <div class='text-xs text-muted'>Producto seleccionado</div>          <div class='font-bold text-sm'>{form.nombre}</div>        </div>        <button class='text-xs text-primary font-bold' onclick={() => { form.productoId = ''; form.nombre = ''; }}>Cambiar</button>      </div>      {#if !form.varianteId}        <div class='mb-2'>          <div class='text-xs font-extrabold text-muted mb-2'>Selecciona variante:</div>          {#each variantesDeProducto(form.productoId) as v}            {@const s = stockVariante(lotes, v.id)}            <button class='w-full flex justify-between items-center px-3.5 py-3 text-left border border-border/50 rounded-[var(--radius-md)] mb-1.5 text-sm cursor-pointer transition-colors hover:bg-background active:bg-background' onclick={() => seleccionarVariante(v)}>              <span class='font-medium'>{v.nombre} {#if v.esCaja}<span class='text-primary text-xs'>(Caja x{v.unidadesPorCaja})</span>{/if}</span>              <span class='text-xs text-muted'>Stock: {fmtCant(s)} {v.unidad || ''} · {fmt(v.precioBase)}</span>            </button>          {/each}        </div>      {:else}        {@const vSel = variantes.find(x => x.id === form.varianteId)}        <div class='bg-success/5 rounded-xl p-3 mb-3 flex justify-between items-center'>          <div>            <div class='text-xs text-muted'>Variante</div>            <div class='font-bold text-sm'>{vSel?.nombre || ''} {#if vSel?.esCaja}<span class='text-primary text-xs'>(Caja x{vSel.unidadesPorCaja})</span>{/if}</div>          </div>          <button class='text-xs text-primary font-bold' onclick={() => form.varianteId = ''}>Cambiar</button>        </div>        <div class='grid grid-cols-2 gap-2 mb-2'>          <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' type='number' inputmode='decimal' step='0.001' placeholder='Cantidad' bind:value={form.cantidad} />          <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' type='number' inputmode='decimal' step='0.01' placeholder='Costo unit.' bind:value={form.costo} />        </div>        {#if n(form.cantidad) > 0 && n(form.costo) >= 0}          <div class='bg-danger/5 rounded-xl p-3 mb-3 text-center'>            <div class='text-xs text-muted'>Total de la compra</div>            <div class='text-xl font-extrabold text-danger'>{fmt(n(form.cantidad) * n(form.costo))}</div>          </div>        {/if}        <button class='w-full py-3 rounded-[var(--radius-md)] bg-primary text-white font-extrabold text-sm mb-2 active:scale-[0.97] transition-transform disabled:opacity-50' onclick={guardarCompra} disabled={procesando}>          <Icono nombre='bag' size={16} color='#fff' />          {procesando ? 'Guardando...' : (form.editId ? 'Actualizar' : 'Registrar') + ' Compra'}        </button>        <button class='w-full py-3 rounded-[var(--radius-md)] border border-border bg-transparent text-text font-extrabold text-sm active:scale-[0.97] transition-transform disabled:opacity-50' onclick={resetForm} disabled={procesando}>Cancelar</button>      {/if}    {/if}  </div>  <!-- Historial --><div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)]'>    <div class='flex items-center gap-2 font-extrabold text-primary mb-3'>      <Icono nombre='history' size={18} />      Historial de Compras    </div>    {#if comprasPaginadas.length === 0}      <div class='text-center text-muted py-6 text-sm'>Sin compras</div>    {:else}      {#each comprasPaginadas as c}        <div class='flex justify-between items-center gap-2 py-3 border-b border-border'>          <div class='min-w-0 flex-1'>            <div class='flex items-center gap-1.5 font-bold text-sm'>              <div class='w-2 h-2 rounded-full bg-danger'></div>              {c.productoNombre}            </div>            <div class='text-xs text-muted mt-0.5'>{fmtFH(c.fecha)} · {fmtCant(c.cantidad)} {c.unidad || ''} × {fmt(c.costo)}</div>          </div>          <div class='flex items-center gap-1 flex-shrink-0'>            <b class='text-danger'>{fmt(c.total)}</b>            {#if esCerrado(c.fecha)}              <span class='inline-block px-2 py-0.5 rounded-full text-[0.6rem] font-extrabold text-white bg-warning'>CERRADO</span>            {:else if loteSinVentas(c.id)}              <button class='w-8 h-8 rounded-lg bg-background flex items-center justify-center border-none cursor-pointer disabled:opacity-30 active:scale-[0.92] transition-transform' aria-label='Editar compra' onclick={() => editar(c)} disabled={procesando}>                <Icono nombre='edit' size={15} />              </button>              <button class='w-8 h-8 rounded-lg bg-danger/10 flex items-center justify-center border-none cursor-pointer disabled:opacity-30 active:scale-[0.92] transition-transform' aria-label='Eliminar compra' onclick={() => eliminar(c)} disabled={procesando}>                <Icono nombre='trash' size={15} color='#dc2626' />              </button>            {:else}              <span title='Con ventas: no editable'><Icono nombre='lock' size={15} /></span>            {/if}          </div>        </div>      {/each}      {#if totalPaginas > 1}        <div class='flex justify-center items-center gap-2 mt-3 text-sm'>          <button class='px-3 py-1 rounded-md border border-border bg-card disabled:opacity-30 active:scale-[0.95] transition-transform' onclick={() => paginaHist--} disabled={paginaHist <= 1}>←</button>          <span class='text-muted'>{paginaHist} / {totalPaginas}</span>          <button class='px-3 py-1 rounded-md border border-border bg-card disabled:opacity-30 active:scale-[0.95] transition-transform' onclick={() => paginaHist++} disabled={paginaHist >= totalPaginas}>→</button>        </div>      {/if}    {/if}  </div></div>